  ('00000000-0000-4000-8000-00015a1d0016', 22, 4, 'patience is the key to relief.'),
  ('00000000-0000-4000-8000-00015a1d0017', 23, 4, 'whoever works hard finds success; whoever plants, harvests.'),
  ('00000000-0000-4000-8000-00015a1d0018', 24, 4, 'time is like a sword: if you do not cut it, it cuts you.'),
  ('00000000-0000-4000-8000-00015a1d0019', 25, 4, 'learning when young is like carving in stone.'),
  ('00000000-0000-4000-8000-00015a1d001a', 26, 4, 'a friend in need is a friend indeed.'),
  ('00000000-0000-4000-8000-00015a1d001b', 27, 4, 'speech is silver, silence is golden.'),
  ('00000000-0000-4000-8000-00015a1d001c', 28, 5, 'the journey of a thousand miles begins with a single step.'),
  ('00000000-0000-4000-8000-00015a1d001d', 29, 5, 'where there''s a will, there''s a way.'),
  ('00000000-0000-4000-8000-00015a1d001e', 30, 5, 'rome wasn''t built in a day.'),
  ('00000000-0000-4000-8000-00015a1d001f', 31, 5, 'fall seven times, stand up eight.'),
  ('00000000-0000-4000-8000-00015a1d0020', 32, 5, 'two heads are better than one.'),
  ('00000000-0000-4000-8000-00015a1d0021', 33, 5, 'honesty is the best policy.'),
  ('00000000-0000-4000-8000-00015a1d0022', 34, 5, 'look before you leap.'),
  ('00000000-0000-4000-8000-00015a1d0023', 35, 5, 'little by little, the bird builds its nest.')) as x(id, k, u, hw)
join public.words w on w.lang = 'en' and lower(w.headword) = x.hw and w.sense = ''
on conflict (id) do nothing;

-- link each saying to the dictionary words in it (not to other sayings, idioms or phrasal verbs)
insert into public.word_partners (word_id, kind, phrase, partner, partner_word_id, position, owner_id)
select distinct on (d.id, s.id) d.id, 'saying', s.headword, d.headword, s.id, 900, (select p.id from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com')
from public.set_entries e join public.words s on s.id = e.word_id
cross join lateral regexp_split_to_table(lower(s.headword), '[^a-z]+') tok
join public.words d on d.lang = 'en' and d.sense = '' and lower(d.headword) = tok and d.id <> s.id
where e.set_id = '00000000-0000-4000-8000-000000005a1d' and length(tok) >= 4 and tok <> all (array['have','will','with','that','this','what','your','from','they','there','than','when','then','which','only','more','most'])
  and not (d.tags && array['Saying','Idiom','Phrasal verb'])
on conflict (word_id, lower(phrase)) do nothing;

-- check
select (select count(*) from public.set_items where set_id = '00000000-0000-4000-8000-000000005a1d') as sayings,
       (select count(*) from public.set_items where set_id = '00000000-0000-4000-8000-000000005a1d' and author <> '') as with_author,
       (select count(*) from public.word_partners where kind = 'saying') as word_links,
       (select string_agg(distinct partner, ', ') from public.word_partners where kind = 'saying') as linked_words;
